'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var namedtypedtuple = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple has an `at` method', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	t.strictEqual( hasOwnProp( p, 'at' ), true, 'returns expected value' );
	t.strictEqual( isFunction( p.at ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a tuple instance', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.at.call( value, 0 );
		};
	}
});

tape( 'the method throws an error if provided a first argument which is not an integer', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.at( value );
		};
	}
});

tape( 'the method returns the tuple element at a specified index', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1.0, 2.0, 3.0 ] );

	t.strictEqual( p.at( 0 ), 1.0, 'returns expected value' );
	t.strictEqual( p.at( 1 ), 2.0, 'returns expected value' );
	t.strictEqual( p.at( 2 ), 3.0, 'returns expected value' );
	t.end();
});

tape( 'the method supports negative indices', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1.0, 2.0, 3.0 ] );

	t.strictEqual( p.at( -1 ), 3.0, 'returns expected value' );
	t.strictEqual( p.at( -2 ), 2.0, 'returns expected value' );
	t.strictEqual( p.at( -3 ), 1.0, 'returns expected value' );
	t.end();
});

tape( 'the method returns `undefined` if provided an out-of-bounds index', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1.0, 2.0, 3.0 ] );

	t.strictEqual( p.at( 3 ), void 0, 'returns expected value' );
	t.strictEqual( p.at( 100 ), void 0, 'returns expected value' );
	t.strictEqual( p.at( -4 ), void 0, 'returns expected value' );
	t.strictEqual( p.at( -100 ), void 0, 'returns expected value' );
	t.end();
});
